export const HOME_MODES=Object.freeze(['EARTH','FOCUS','LAYER','INTELLIGENCE']);
export function createHomeState(overrides={}){return Object.freeze({schemaVersion:'earthus.home.v1',mode:'EARTH',activeScene:'LAND',activePrimaryEngine:null,activeContextEngine:null,selectedFeatureId:null,intelligenceOpen:false,menuOpen:false,dataState:'IDLE',...overrides})}
export function reduceHomeState(state,action){if(!HOME_MODES.includes(state?.mode))throw new TypeError('invalid home state');switch(action?.type){case'MENU_TOGGLE':return createHomeState({...state,menuOpen:!state.menuOpen});case'INTELLIGENCE_TOGGLE':return createHomeState({...state,intelligenceOpen:!state.intelligenceOpen,mode:!state.intelligenceOpen?'INTELLIGENCE':state.activePrimaryEngine?'LAYER':'EARTH'});case'SELECT_LAYER':return createHomeState({...state,mode:'LAYER',activePrimaryEngine:action.engineId??null,activeContextEngine:action.contextEngineId??null,dataState:action.dataState??'LOADING'});case'CLEAR_LAYER':return createHomeState({...state,mode:'EARTH',activePrimaryEngine:null,activeContextEngine:null,selectedFeatureId:null,dataState:'IDLE'});case'SELECT_FEATURE':return createHomeState({...state,mode:'FOCUS',selectedFeatureId:action.featureId??null});default:return state}}
